  1	/**
  2	 * tests/builders/on-persona-partials.test.ts
  3	 *
  4	 * Tests for WP-005 — onPersonaPartials Hook Wiring in buildPersona()
  5	 *
  6	 * Verifies all 7 Acceptance Criteria:
  7	 *   AC-1: An onPersonaPartials plugin can inject a partial resolvable as {{> partialName}}
  8	 *   AC-2: An onPersonaPartials plugin can override a suite-level partial for a single persona
  9	 *   AC-3: Persona-level partial overrides do not leak to other personas (shallow copy isolation)
 10	 *   AC-4: The hook receives the post-onBuildContext context (persona metadata is accessible)
 11	 *   AC-5: The hook receives the current target value
 12	 *   AC-6: Project compiles without errors (verified by build step)
 13	 *   AC-7: All existing tests continue to pass unchanged (verified by running full suite)
 14	 */
 15	
 16	import { describe, it, expect, beforeEach, afterEach } from 'vitest';
 17	import { mkdir, writeFile, rm } from 'node:fs/promises';
 18	import { tmpdir } from 'node:os';
 19	import path from 'node:path';
 20	
 21	import { buildSuite } from '../../src/builders/persona-builder.js';
 22	import type { BuildConfig } from '../../src/builders/types.js';
 23	import type { PersonaBuildPlugin, SuiteConfig } from '../../src/plugins/types.js';
 24	
 25	// ---------------------------------------------------------------------------
 26	// Temp directory helpers
 27	// ---------------------------------------------------------------------------
 28	
 29	let testTmpDir: string;
 30	
 31	beforeEach(async () => {
 32	  testTmpDir = path.join(
 33	    tmpdir(),
 34	    `wp005-persona-partials-${Date.now()}-${Math.random().toString(36).slice(2)}`,
 35	  );
 36	  await mkdir(testTmpDir, { recursive: true });
 37	});
 38	
 39	afterEach(async () => {
 40	  await rm(testTmpDir, { recursive: true, force: true });
 41	});
 42	
 43	// ---------------------------------------------------------------------------
 44	// Helper: build a minimal single-persona suite
 45	// ---------------------------------------------------------------------------
 46	
 47	interface SuiteFixture {
 48	  suiteDir: string;
 49	  outDir: string;
 50	  suiteConfig: SuiteConfig;
 51	}
 52	
 53	async function createSuite(opts: {
 54	  /** Content template for the persona */
 55	  contentMd?: string;
 56	  /** Persona YAML content */
 57	  personaYaml?: string;
 58	  /** Suite-local partials: name → content */
 59	  suitePartials?: Record<string, string>;
 60	}): Promise<SuiteFixture> {
 61	  const suiteDir = path.join(testTmpDir, 'suite');
 62	  const outDir = path.join(testTmpDir, 'out');
 63	
 64	  await mkdir(path.join(suiteDir, 'meta'), { recursive: true });
 65	  await mkdir(path.join(suiteDir, 'content'), { recursive: true });
 66	  await mkdir(path.join(suiteDir, 'partials'), { recursive: true });
 67	
 68	  // _shared.yaml
 69	  await writeFile(
 70	    path.join(suiteDir, 'meta', '_shared.yaml'),
 71	    'default_version: "1.0.0"\n',
 72	  );
 73	
 74	  // persona YAML
 75	  await writeFile(
 76	    path.join(suiteDir, 'meta', 'agent.yaml'),
 77	    opts.personaYaml ??
 78	      'name: Test Agent\nvs_file_name: agent.agent.md\ncc_file_name: agent.md\n',
 79	  );
 80	
 81	  // content template
 82	  await writeFile(
 83	    path.join(suiteDir, 'content', 'agent.md'),
 84	    opts.contentMd ?? '# Test\n',
 85	  );
 86	
 87	  // suite-local partials
 88	  if (opts.suitePartials) {
 89	    for (const [name, content] of Object.entries(opts.suitePartials)) {
 90	      await writeFile(path.join(suiteDir, 'partials', `${name}.md`), content);
 91	    }
 92	  }
 93	
 94	  const suiteConfig: SuiteConfig = {
 95	    srcDir: suiteDir,
 96	    outVscode: outDir,
 97	    outClaudeCode: outDir,
 98	  };
 99	
100	  return { suiteDir, outDir, suiteConfig };

101	}
102	
103	// ---------------------------------------------------------------------------
104	// Helper: build a two-persona suite for isolation tests
105	// ---------------------------------------------------------------------------
106	
107	async function createTwoPersonaSuite(opts: {
108	  /** Content template for persona-a */
109	  contentA?: string;
110	  /** Content template for persona-b */
111	  contentB?: string;
112	  /** Suite-local partials: name → content */
113	  suitePartials?: Record<string, string>;
114	}): Promise<SuiteFixture> {
115	  const suiteDir = path.join(testTmpDir, 'suite');
116	  const outDir = path.join(testTmpDir, 'out');
117	
118	  await mkdir(path.join(suiteDir, 'meta'), { recursive: true });
119	  await mkdir(path.join(suiteDir, 'content'), { recursive: true });
120	  await mkdir(path.join(suiteDir, 'partials'), { recursive: true });
121	
122	  await writeFile(
123	    path.join(suiteDir, 'meta', '_shared.yaml'),
124	    'default_version: "1.0.0"\n',
125	  );
126	
127	  // Persona A
128	  await writeFile(
129	    path.join(suiteDir, 'meta', 'agent-a.yaml'),
130	    'name: Agent A\nvs_file_name: agent-a.agent.md\ncc_file_name: agent-a.md\n',
131	  );
132	  await writeFile(
133	    path.join(suiteDir, 'content', 'agent-a.md'),
134	    opts.contentA ?? '# Agent A\n',
135	  );
136	
137	  // Persona B
138	  await writeFile(
139	    path.join(suiteDir, 'meta', 'agent-b.yaml'),
140	    'name: Agent B\nvs_file_name: agent-b.agent.md\ncc_file_name: agent-b.md\n',
141	  );
142	  await writeFile(
143	    path.join(suiteDir, 'content', 'agent-b.md'),
144	    opts.contentB ?? '# Agent B\n',
145	  );
146	
147	  // Suite-local partials
148	  if (opts.suitePartials) {
149	    for (const [name, content] of Object.entries(opts.suitePartials)) {
150	      await writeFile(path.join(suiteDir, 'partials', `${name}.md`), content);
151	    }
152	  }
153	
154	  const suiteConfig: SuiteConfig = {
155	    srcDir: suiteDir,
156	    outVscode: outDir,
157	    outClaudeCode: outDir,
158	  };
159	
160	  return { suiteDir, outDir, suiteConfig };
161	}
162	
163	// ---------------------------------------------------------------------------
164	// AC-1: onPersonaPartials plugin can inject a new partial resolvable in the template
165	// ---------------------------------------------------------------------------
166	
167	describe('AC-1 — onPersonaPartials plugin can inject a new partial', () => {
168	  it('a plugin-injected partial is resolved in the persona content template', async () => {
169	    const plugin: PersonaBuildPlugin = {
170	      name: 'persona-partial-injector',
171	      onPersonaPartials(partialsMap) {
172	        return { ...partialsMap, 'persona-greeting': 'Hello from persona partial.' };
173	      },
174	    };
175	
176	    const { suiteConfig } = await createSuite({
177	      contentMd: '{{> persona-greeting}}\n',
178	    });
179	
180	    const config: BuildConfig = {
181	      suites: { 'test-suite': suiteConfig },
182	      targets: ['vscode'],
183	    };
184	
185	    const results = await buildSuite('test-suite', suiteConfig, config, [plugin], 'vscode');
186	
187	    expect(results).toHaveLength(1);
188	    expect(results[0].content).toContain('Hello from persona partial.');
189	  });
190	
191	  it('multiple plugins accumulate — later plugin receives and can extend earlier output', async () => {
192	    const firstPlugin: PersonaBuildPlugin = {
193	      name: 'first',
194	      onPersonaPartials(partialsMap) {
195	        return { ...partialsMap, part1: 'Part 1 content.' };
196	      },
197	    };
198	
199	    const secondPlugin: PersonaBuildPlugin = {
200	      name: 'second',
201	      onPersonaPartials(partialsMap) {
202	        // Should already have part1 from firstPlugin
203	        expect(partialsMap['part1']).toBe('Part 1 content.');
204	        return { ...partialsMap, part2: 'Part 2 content.' };
205	      },
206	    };
207	
208	    const { suiteConfig } = await createSuite({
209	      contentMd: '{{> part1}}\n{{> part2}}\n',
210	    });
211	
212	    const config: BuildConfig = {
213	      suites: { 'test-suite': suiteConfig },
214	      targets: ['vscode'],
215	    };
216	
217	    const results = await buildSuite('test-suite', suiteConfig, config, [firstPlugin, secondPlugin], 'vscode');
218	
219	    expect(results[0].content).toContain('Part 1 content.');
220	    expect(results[0].content).toContain('Part 2 content.');
221	  });
222	
223	  it('plugins without onPersonaPartials are skipped gracefully', async () => {
224	    const noHookPlugin: PersonaBuildPlugin = {
225	      name: 'no-hook',
226	      // No onPersonaPartials
227	    };
228	
229	    const { suiteConfig } = await createSuite({
230	      suitePartials: { greeting: 'Suite greeting.' },
231	      contentMd: '{{> greeting}}\n',
232	    });
233	
234	    const config: BuildConfig = {
235	      suites: { 'test-suite': suiteConfig },
236	      targets: ['vscode'],
237	    };
238	
239	    const results = await buildSuite('test-suite', suiteConfig, config, [noHookPlugin], 'vscode');
240	
241	    expect(results[0].content).toContain('Suite greeting.');
242	  });
243	});
244	
245	// ---------------------------------------------------------------------------
246	// AC-2: onPersonaPartials plugin can override a suite-level partial for one persona
247	// ---------------------------------------------------------------------------
248	
249	describe('AC-2 — onPersonaPartials can override a suite-level partial', () => {
250	  it('persona-level override wins over the suite-level partial of the same name', async () => {
251	    const plugin: PersonaBuildPlugin = {
252	      name: 'suite-overrider',
253	      onPersonaPartials(partialsMap) {
254	        return { ...partialsMap, greeting: 'Persona-level greeting.' };
255	      },
256	    };
257	
258	    const { suiteConfig } = await createSuite({
259	      suitePartials: { greeting: 'Suite-level greeting.' },
260	      contentMd: '{{> greeting}}\n',
261	    });
262	
263	    const config: BuildConfig = {
264	      suites: { 'test-suite': suiteConfig },
265	      targets: ['vscode'],
266	    };
267	
268	    const results = await buildSuite('test-suite', suiteConfig, config, [plugin], 'vscode');
269	
270	    expect(results[0].content).toContain('Persona-level greeting.');
271	    expect(results[0].content).not.toContain('Suite-level greeting.');
272	  });
273	
274	  it('persona-level override wins over a config.partials entry of the same name', async () => {
275	    const plugin: PersonaBuildPlugin = {
276	      name: 'config-overrider',
277	      onPersonaPartials(partialsMap) {
278	        return { ...partialsMap, note: 'Note overridden at persona level.' };
279	      },
280	    };
281	
282	    const { suiteConfig } = await createSuite({
283	      contentMd: '{{> note}}\n',
284	    });
285	
286	    const config: BuildConfig = {
287	      suites: { 'test-suite': suiteConfig },
288	      targets: ['vscode'],
289	      partials: { note: 'Config-level note.' },
290	    };
291	
